package com.example.demo;

import org.apache.kafka.clients.admin.NewTopic;
import org.apache.kafka.common.TopicPartition;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.config.TopicBuilder;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.kafka.listener.DeadLetterPublishingRecoverer;
import org.springframework.kafka.listener.DefaultErrorHandler;
import org.springframework.util.backoff.FixedBackOff;

@Configuration
class KafkaFailureConfiguration {
    @Bean
    NewTopic failedDigests() {
        return TopicBuilder.name("weekly-sentiments.DLT")
                .partitions(1).replicas(1).build();
    }

    @Bean
    DefaultErrorHandler digestErrorHandler(KafkaTemplate<String, String> kafka) {
        var recoverer = new DeadLetterPublishingRecoverer(kafka,
                (record, failure) -> new TopicPartition(
                        "weekly-sentiments.DLT", record.partition()));
        recoverer.setFailIfSendResultIsError(true);
        var handler = new DefaultErrorHandler(recoverer,
                new FixedBackOff(1000L, 2L));
        handler.addNotRetryableExceptions(IllegalArgumentException.class);
        return handler;
    }
}

package com.example.demo;

import java.util.concurrent.TimeUnit;
import org.apache.kafka.clients.admin.NewTopic;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.ApplicationRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.config.TopicBuilder;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;
import com.fasterxml.jackson.databind.ObjectMapper;

@Configuration
class DigestKafkaConfiguration {
    @Bean
    NewTopic digestTopic() {
        return TopicBuilder.name("weekly-sentiments")
                .partitions(1).replicas(1).build();
    }

    @Bean
    ApplicationRunner publishDigest(KafkaTemplate<String, String> kafka) {
        return args -> {
            String json = """
                {"version":1,"eventId":"digest-42-2026-W41","userId":"user-42","summary":"HAPPY=2, SAD=1"}
                """;
            kafka.send("weekly-sentiments", "user-42", json)
                    .get(5, TimeUnit.SECONDS);
        };
    }
}

package com.example.demo;

import java.util.concurrent.TimeUnit;
import org.apache.kafka.clients.admin.NewTopic;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;
import org.springframework.boot.ApplicationRunner;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Configuration;
import org.springframework.kafka.annotation.KafkaListener;
import org.springframework.kafka.config.TopicBuilder;
import org.springframework.kafka.core.KafkaTemplate;
import org.springframework.stereotype.Component;
import com.fasterxml.jackson.databind.ObjectMapper;

@Component
class DigestListener {
    private static final Logger log = LoggerFactory.getLogger(DigestListener.class);
    private final ObjectMapper mapper;

    DigestListener(ObjectMapper mapper) {
        this.mapper = mapper;
    }

    @KafkaListener(topics = "weekly-sentiments", groupId = "weekly-digest-mail")
    void receive(String json) throws Exception {
        Digest event = mapper.readValue(json, Digest.class);
        if (event.version() != 1 || event.eventId() == null
                || event.eventId().isBlank() || event.userId() == null
                || event.summary() == null) {
            throw new IllegalArgumentException("Invalid digest event");
        }
        log.info("Validated digest record");
    }

    record Digest(int version, String eventId, String userId, String summary) {}
}

